SELECT CASE WHEN institution_type ILIKE '%Hospital%' THEN 'H' ELSE 'L' END AS seg, COALESCE(provider_economic_group, TRIM(institution_name)) AS grupo, DATE_TRUNC('month', disallowance_date)::date AS mes_glosa,
 SUM(disallowance_value) AS glosado,
 SUM(CASE WHEN appeal_value IS NOT NULL AND appeal_date <= '2026-11-17' AND NOT (COALESCE(provider_economic_group,'') = 'DASA' AND disallowance_date < '2026-01-01' AND appeal_date >= '2026-09-01') AND NOT COALESCE(disallowance_reason ILIKE '%7F6%' AND appeal_date >= '2026-07-01' AND appeal_date < '2026-09-01', FALSE) THEN appeal_value ELSE 0 END) AS rec_tot,
 SUM(CASE WHEN appeal_value IS NOT NULL AND appeal_date <= '2026-11-17' AND (appeal_date::date - disallowance_date::date) <= 45 AND NOT (COALESCE(provider_economic_group,'') = 'DASA' AND disallowance_date < '2026-01-01' AND appeal_date >= '2026-09-01') AND NOT COALESCE(disallowance_reason ILIKE '%7F6%' AND appeal_date >= '2026-07-01' AND appeal_date < '2026-09-01', FALSE) THEN appeal_value ELSE 0 END) AS rec45,
 SUM(CASE WHEN appeal_value IS NOT NULL AND appeal_date <= '2026-11-17' AND (appeal_date::date - disallowance_date::date) <= 60 AND NOT (COALESCE(provider_economic_group,'') = 'DASA' AND disallowance_date < '2026-01-01' AND appeal_date >= '2026-09-01') AND NOT COALESCE(disallowance_reason ILIKE '%7F6%' AND appeal_date >= '2026-07-01' AND appeal_date < '2026-09-01', FALSE) THEN appeal_value ELSE 0 END) AS rec60
FROM curated.totvs_procedure_invoice WHERE system_source = 'totvs-alice' AND provider_class = 'Health Institution' AND invoice_step IN ('1-Digitacao','2-Conferencia','3-Pronta','4-Faturada') AND (institution_type ILIKE '%Clinica%' OR institution_type ILIKE '%Laboratorio%' OR institution_type ILIKE '%Hospital%') AND disallowance_value > 0 AND disallowance_date >= '2026-04-01' AND disallowance_date <= '2026-11-17' GROUP BY 1,2,3 HAVING SUM(disallowance_value) > 20000
